{
  "licensingBody": "Medical and Dental Council of Nigeria (MDCN)",
  "licenseNumber": "MDCN/2018/48291",
  "specialty": "Chemical Pathology",
  "expiryDate": "2028-12-31"
}

{
  "newOwnerEmail": "new.owner@everight.com",
  "newOwnerName": "Dr. Amaka Nwosu",
  "notes": "Ownership transferred as part of acquisition"
}

{
  "channel": "EMAIL",
  "subject": "Your Diagnostic Report Is Ready",
  "bodyTemplate": "<p>Dear {{patientName}}, your report for {{testName}} is ready.</p>",
  "allowedVariables": ["patientName", "testName", "resultUrl"]
}

{
  "userId": "{{user_id}}",
  "type": "RESULT_READY",
  "title": "Diagnostic Results Available",
  "body": "Your Full Blood Count report is authorized."
}

{
  "recipientId": "{{user_id}}",
  "subject": "Urgent: Sample Rerun Required",
  "body": "Please rerun specimen #BC-89210-EDTA for FBC differential."
}

{
  "patientId": "{{patient_id}}",
  "visitType": "outpatient",
  "chiefComplaint": "High fever, rigors and fatigue for 3 days",
  "vitals": {
    "temperature": 38.8,
    "bloodPressure": "120/80",
    "pulseRate": 82,
    "weightKg": 72.5
  }
}

{
  "orderId": "{{order_id}}",
  "testCode": "FBC",
  "parameters": [
    { "name": "Hemoglobin", "value": "14.2", "unit": "g/dL", "flag": "NORMAL", "referenceRange": "13.0 - 17.0" },
    { "name": "White Blood Cell Count", "value": "12.8", "unit": "x10^9/L", "flag": "HIGH", "referenceRange": "4.0 - 11.0" },
    { "name": "Platelets", "value": "240", "unit": "x10^9/L", "flag": "NORMAL", "referenceRange": "150 - 450" }
  ],
  "technicianNotes": "Sample processed on Sysmex XN-550. No clots detected."
}

{
  "orderId": "{{order_id}}",
  "authorizerNotes": "Results reviewed and authorized for clinical correlation."
}
